SELECT set_config('search_path', 'pg_catalog, extensions, pg_temp', true);

-- ===== Body of db/sql/0001_territorial_registry.up.sql (unchanged) =====
-- GEONAF migration 0001: territorial registry (read-only copy of the file registry, D2-a).
--
-- The file registry (data/territories, src/data/territory_registry.py) stays the reference until D4.
-- Every row is immutable: a new version is a new row, never an update. The original record is kept
-- verbatim in record_document so that its SHA-256 fingerprint can be recomputed in Python; the
-- columns exist for queries and constraints and are checked against the document at import.
-- Areas are never recomputed here: area_km2 is GEONAF's EPSG:6933 computation, copied as recorded.
--
-- Conventions: every object is schema-qualified; functions run with an empty search_path; no
-- percent sign (the file is sent to the driver as is); lists copied from Python are checked by tests.
-- Platforms: local PostgreSQL (Alembic, db/migrations) and Supabase (SQL Editor, db/supabase), same body.

-- Preconditions. The migration never installs an extension: PostGIS is enabled beforehand by an
-- administrator (Supabase: schema "extensions"; postgis/postgis image: preinstalled). Its schema must
-- be on the search_path while this file runs, so that the type geometry resolves.
DO $$
DECLARE
  postgis_version text := (SELECT extversion FROM pg_extension WHERE extname = 'postgis');
BEGIN
  IF current_setting('server_version_num')::integer < 150000 THEN
    RAISE EXCEPTION 'GEONAF: PostgreSQL 15 ou plus requis (UNIQUE NULLS NOT DISTINCT)';
  END IF;
  IF postgis_version IS NULL THEN
    RAISE EXCEPTION 'GEONAF: extension PostGIS absente, à activer par un administrateur';
  END IF;
  IF split_part(postgis_version, '.', 1)::integer * 100 + split_part(postgis_version, '.', 2)::integer < 303 THEN
    RAISE EXCEPTION 'GEONAF: PostGIS 3.3 ou plus requis' USING DETAIL = 'version ' || postgis_version;
  END IF;
  IF to_regtype('geometry') IS NULL THEN
    RAISE EXCEPTION 'GEONAF: type geometry introuvable, ajouter le schéma de PostGIS au search_path';
  END IF;
END $$;

CREATE SCHEMA geonaf;
REVOKE ALL ON SCHEMA geonaf FROM PUBLIC;

-- Reference data ------------------------------------------------------------------------------

CREATE TABLE geonaf.licences (
  licence_id      text PRIMARY KEY CHECK (licence_id ~ '^[A-Za-z0-9.+-]+$'),   -- SPDX or LicenseRef-*
  name            text NOT NULL CHECK (btrim(name) <> ''),
  url             text CHECK (url IS NULL OR url ~ '^https://'),
  share_alike     boolean NOT NULL,
  commercial_use  boolean,           -- NULL: not assessed (no legal statement made by GEONAF)
  redistribution  boolean,           -- NULL: not assessed
  reviewed_note   text
);

INSERT INTO geonaf.licences (licence_id, name, url, share_alike) VALUES
  ('CC-BY-3.0', 'Creative Commons Attribution 3.0 Unported',
   'https://creativecommons.org/licenses/by/3.0/', false),
  ('CC-BY-3.0-IGO', 'Creative Commons Attribution 3.0 IGO',
   'https://creativecommons.org/licenses/by/3.0/igo/', false),
  ('LicenseRef-GEONAF', 'Zones de travail GEONAF', NULL, false);

CREATE TABLE geonaf.data_sources (
  source_id   text PRIMARY KEY CHECK (btrim(source_id) <> ''),
  provider    text,
  nature      text,
  access_tier text NOT NULL DEFAULT 'public' CHECK (access_tier IN ('public', 'restricted', 'commercial'))
);

-- One release = every field of TerritorySource except retrieved_at_utc (kept per version).
CREATE TABLE geonaf.source_releases (
  release_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source_id      text NOT NULL REFERENCES geonaf.data_sources,
  product        text NOT NULL CHECK (btrim(product) <> ''),
  version        text NOT NULL CHECK (btrim(version) <> ''),
  licence_id     text NOT NULL REFERENCES geonaf.licences,
  attribution    text NOT NULL CHECK (btrim(attribution) <> ''),
  url            text,
  share_alike    boolean NOT NULL,
  reference_year integer CHECK (reference_year BETWEEN 1800 AND 2200),
  UNIQUE NULLS NOT DISTINCT (source_id, product, version, licence_id, attribution, url, share_alike,
                             reference_year)
);

-- Geometries, addressed by their normalized fingerprint (src/geo/aoi_identity.py) -----------------

-- geom is the WGS84 union used by the application (not rounded), stored as MultiPolygon.
-- source_geometry_type keeps the union's own type: the fingerprint hashes the WKB of a Polygon
-- when the union is a Polygon, so the conversion must be reversible.
CREATE TABLE geonaf.geometries (
  geometry_sha256      char(64) PRIMARY KEY CHECK (geometry_sha256 ~ '^[0-9a-f]{64}$'),
  identity_version     text NOT NULL CHECK (identity_version = 'geonaf-aoi-geometry-v1'),
  source_geometry_type text NOT NULL CHECK (source_geometry_type IN ('Polygon', 'MultiPolygon')),
  geom                 geometry(MultiPolygon, 4326) NOT NULL,
  parts                integer NOT NULL CHECK (parts >= 1),
  vertices             integer NOT NULL CHECK (vertices >= 4),
  CHECK (ST_IsValid(geom) AND NOT ST_IsEmpty(geom)),
  CHECK (ST_NumGeometries(geom) = parts),
  CHECK (ST_NPoints(geom) = vertices),
  CHECK (source_geometry_type = 'MultiPolygon' OR parts = 1),
  CHECK (ST_XMin(geom) >= -180 AND ST_XMax(geom) <= 180 AND ST_YMin(geom) >= -90 AND ST_YMax(geom) <= 90)
);
CREATE INDEX geometries_geom_gist ON geonaf.geometries USING gist (geom);

-- Territories -----------------------------------------------------------------------------------

CREATE TABLE geonaf.territory_kinds (kind text PRIMARY KEY);
INSERT INTO geonaf.territory_kinds (kind) VALUES
  ('acquisition_zone'), ('admin_unit'), ('custom_import'), ('grid_cell');

-- Copy of LEGAL_STATUSES (src/data/territory_registry.py).
CREATE TABLE geonaf.legal_statuses (
  kind         text NOT NULL REFERENCES geonaf.territory_kinds,
  legal_status text NOT NULL,
  PRIMARY KEY (kind, legal_status)
);
INSERT INTO geonaf.legal_statuses (kind, legal_status) VALUES
  ('acquisition_zone', 'zone d''acquisition GEONAF'),
  ('admin_unit', 'référentiel communautaire'),
  ('admin_unit', 'référentiel humanitaire (COD)'),
  ('admin_unit', 'officiel vérifié'),
  ('custom_import', 'fourni par l''utilisateur'),
  ('custom_import', 'officiel vérifié'),
  ('grid_cell', 'grille GEONAF');

-- Stable identity. A territory never changes kind: another kind is another territory.
CREATE TABLE geonaf.territories (
  territory_id text PRIMARY KEY CHECK (territory_id ~ '^[a-z0-9][a-z0-9_-]{1,63}$'),
  kind         text NOT NULL REFERENCES geonaf.territory_kinds,
  UNIQUE (territory_id, kind)
);

CREATE TABLE geonaf.registry_imports (
  import_id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  started_at          timestamptz NOT NULL DEFAULT now(),
  finished_at         timestamptz,
  source_label        text NOT NULL CHECK (btrim(source_label) <> '' AND source_label !~ '[/\\:]'),
  code_version        text NOT NULL CHECK (btrim(code_version) <> ''),
  records_seen        integer NOT NULL DEFAULT 0 CHECK (records_seen >= 0),
  records_inserted    integer NOT NULL DEFAULT 0 CHECK (records_inserted >= 0),
  records_existing    integer NOT NULL DEFAULT 0 CHECK (records_existing >= 0),
  fingerprints_sha256 char(64)
);

CREATE TABLE geonaf.territory_versions (
  territory_id          text NOT NULL,
  version               integer NOT NULL CHECK (version >= 1),
  kind                  text NOT NULL,
  label                 text NOT NULL CHECK (btrim(label) <> ''),
  legal_status          text NOT NULL,
  legal_evidence        text,
  release_id            bigint NOT NULL REFERENCES geonaf.source_releases,
  retrieved_at_utc      text,                            -- original text, see record_document
  geometry_sha256       char(64) NOT NULL REFERENCES geonaf.geometries,
  file_sha256           char(64) NOT NULL CHECK (file_sha256 ~ '^[0-9a-f]{64}$'),
  storage_key           text NOT NULL CHECK (storage_key ~ '^geometries/[0-9a-f]{64}[.]geojson$'),
  wgs84_bounds          double precision[] NOT NULL CHECK (cardinality(wgs84_bounds) = 4),
  area_km2              double precision NOT NULL CHECK (area_km2 > 0),
  vertices              integer NOT NULL,
  parts                 integer NOT NULL,
  created_at_utc        text NOT NULL,
  country_iso3          char(3) CHECK (country_iso3 ~ '^[A-Z]{3}$'),
  admin_level_code      text,
  local_type            text,
  source_unit_id        text,
  parent_territory_id   text REFERENCES geonaf.territories DEFERRABLE INITIALLY DEFERRED,
  grid_system           text,
  grid_cell_id          text,
  grid_cell_size_deg    double precision,
  scientific_profile_id text,
  limits                text[] NOT NULL DEFAULT '{}',
  supersedes            char(64),
  schema                text NOT NULL CHECK (schema = 'geonaf.territory/v1'),
  record_fingerprint    char(64) NOT NULL UNIQUE CHECK (record_fingerprint ~ '^[0-9a-f]{64}$'),
  record_document       jsonb NOT NULL,
  import_id             bigint NOT NULL REFERENCES geonaf.registry_imports,
  PRIMARY KEY (territory_id, version),
  FOREIGN KEY (territory_id, kind) REFERENCES geonaf.territories (territory_id, kind),
  FOREIGN KEY (kind, legal_status) REFERENCES geonaf.legal_statuses (kind, legal_status),
  -- Official only with verifiable evidence (validate_record: at least 8 characters).
  CHECK (legal_status <> 'officiel vérifié' OR length(btrim(coalesce(legal_evidence, ''))) >= 8),
  -- Acquisition zones and grid cells are not administrative units (ADMINISTRATIVE_WORDS).
  CHECK (kind NOT IN ('acquisition_zone', 'grid_cell') OR (country_iso3 IS NULL AND admin_level_code IS NULL
         AND local_type IS NULL AND source_unit_id IS NULL AND parent_territory_id IS NULL)),
  CHECK (kind NOT IN ('acquisition_zone', 'grid_cell') OR lower(label) !~
         '(commune|département|departement|arrondissement|province|district|canton|préfecture|region|région|municipalit)'),
  -- Administrative units declare their country, level and local type.
  CHECK (kind <> 'admin_unit' OR (country_iso3 IS NOT NULL AND btrim(coalesce(admin_level_code, '')) <> ''
         AND btrim(coalesce(local_type, '')) <> '')),
  -- A grid description if and only if a grid cell.
  CHECK ((kind = 'grid_cell') = (grid_system IS NOT NULL AND grid_cell_id IS NOT NULL)),
  -- Version chain: only version 1 has no predecessor.
  CHECK ((version = 1) = (supersedes IS NULL)),
  CHECK (supersedes IS NULL OR supersedes ~ '^[0-9a-f]{64}$'),
  CHECK (jsonb_typeof(record_document) = 'object'
         AND record_document ->> 'territory_id' = territory_id
         AND (record_document ->> 'version')::integer = version
         AND record_document ->> 'geometry_sha256' = geometry_sha256
         AND record_document ->> 'file_sha256' = file_sha256)
);
CREATE INDEX territory_versions_geometry ON geonaf.territory_versions (geometry_sha256);
CREATE INDEX territory_versions_file ON geonaf.territory_versions (file_sha256);
CREATE INDEX territory_versions_release ON geonaf.territory_versions (release_id);
CREATE INDEX territory_versions_admin ON geonaf.territory_versions (country_iso3, admin_level_code);

-- Immutability ------------------------------------------------------------------------------------

CREATE FUNCTION geonaf.forbid_change() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  RAISE EXCEPTION 'GEONAF: changement interdit, les enregistrements sont immuables'
    USING DETAIL = TG_OP || ' sur ' || TG_TABLE_NAME;
END $$;

CREATE TRIGGER licences_immutable BEFORE UPDATE OR DELETE ON geonaf.licences
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER licences_no_truncate BEFORE TRUNCATE ON geonaf.licences
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER data_sources_immutable BEFORE UPDATE OR DELETE ON geonaf.data_sources
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER data_sources_no_truncate BEFORE TRUNCATE ON geonaf.data_sources
