CREATE TRIGGER source_releases_immutable BEFORE UPDATE OR DELETE ON geonaf.source_releases
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER source_releases_no_truncate BEFORE TRUNCATE ON geonaf.source_releases
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER geometries_immutable BEFORE UPDATE OR DELETE ON geonaf.geometries
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER geometries_no_truncate BEFORE TRUNCATE ON geonaf.geometries
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER territory_kinds_immutable BEFORE UPDATE OR DELETE ON geonaf.territory_kinds
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER territory_kinds_no_truncate BEFORE TRUNCATE ON geonaf.territory_kinds
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER legal_statuses_immutable BEFORE UPDATE OR DELETE ON geonaf.legal_statuses
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER legal_statuses_no_truncate BEFORE TRUNCATE ON geonaf.legal_statuses
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER territories_immutable BEFORE UPDATE OR DELETE ON geonaf.territories
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER territories_no_truncate BEFORE TRUNCATE ON geonaf.territories
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER territory_versions_immutable BEFORE UPDATE OR DELETE ON geonaf.territory_versions
  FOR EACH ROW EXECUTE FUNCTION geonaf.forbid_change();
CREATE TRIGGER territory_versions_no_truncate BEFORE TRUNCATE ON geonaf.territory_versions
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();

-- An import journal row may only be closed once (finished_at and counters), never reopened,
-- deleted or re-attributed.
CREATE FUNCTION geonaf.close_import_only() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF TG_OP <> 'UPDATE' OR OLD.finished_at IS NOT NULL OR NEW.finished_at IS NULL
     OR NEW.import_id <> OLD.import_id OR NEW.started_at <> OLD.started_at
     OR NEW.source_label <> OLD.source_label OR NEW.code_version <> OLD.code_version THEN
    RAISE EXCEPTION 'GEONAF: le journal d''import ne peut être que clôturé une fois'
      USING DETAIL = TG_OP || ' sur registry_imports';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER registry_imports_close BEFORE UPDATE OR DELETE ON geonaf.registry_imports
  FOR EACH ROW EXECUTE FUNCTION geonaf.close_import_only();
CREATE TRIGGER registry_imports_no_truncate BEFORE TRUNCATE ON geonaf.registry_imports
  FOR EACH STATEMENT EXECUTE FUNCTION geonaf.forbid_change();

-- Version chain and consistency with the stored geometry.
CREATE FUNCTION geonaf.check_territory_version() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
DECLARE
  previous_fingerprint char(64);
  stored_parts integer;
  stored_vertices integer;
BEGIN
  IF NEW.version > 1 THEN
    SELECT record_fingerprint INTO previous_fingerprint FROM geonaf.territory_versions
     WHERE territory_id = NEW.territory_id AND version = NEW.version - 1;
    IF previous_fingerprint IS NULL OR previous_fingerprint <> NEW.supersedes THEN
      RAISE EXCEPTION 'GEONAF: version sans version précédente correspondante'
        USING DETAIL = NEW.territory_id || ' v' || NEW.version;
    END IF;
  END IF;
  SELECT parts, vertices INTO stored_parts, stored_vertices FROM geonaf.geometries
   WHERE geometry_sha256 = NEW.geometry_sha256;
  IF stored_parts IS DISTINCT FROM NEW.parts OR stored_vertices IS DISTINCT FROM NEW.vertices THEN
    RAISE EXCEPTION 'GEONAF: parties ou sommets incohérents avec la géométrie enregistrée'
      USING DETAIL = NEW.territory_id || ' v' || NEW.version;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER territory_versions_check BEFORE INSERT ON geonaf.territory_versions
  FOR EACH ROW EXECUTE FUNCTION geonaf.check_territory_version();

-- Views -----------------------------------------------------------------------------------------

CREATE VIEW geonaf.territories_latest WITH (security_invoker = true) AS
  SELECT DISTINCT ON (territory_id) * FROM geonaf.territory_versions ORDER BY territory_id, version DESC;

-- The three identities of a zone: geometry (which area), versioned territory (which perimeter, from
-- which source, with which status) and file bytes (existing caches). Basis of the aoi_id resolution.
CREATE VIEW geonaf.territory_identities WITH (security_invoker = true) AS
  SELECT territory_id, version, kind, geometry_sha256, file_sha256, record_fingerprint
  FROM geonaf.territory_versions;

-- Privileges ------------------------------------------------------------------------------------
-- Nothing for PUBLIC nor for the Supabase API roles (anon, authenticated, service_role), even if the
-- schema were one day exposed through the Data API. Row level security is enabled everywhere as a
-- second barrier; the table owner (migrations) is not subject to it. GEONAF roles are created once
-- outside migrations (db/sql/roles.sql, db/supabase/01_roles.sql); grants and policies apply only to
-- the roles that exist, so the migration also runs on a bare test database.
REVOKE ALL ON ALL TABLES IN SCHEMA geonaf FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA geonaf FROM PUBLIC;

ALTER TABLE geonaf.licences ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.data_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.source_releases ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.geometries ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.territory_kinds ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.legal_statuses ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.territories ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.registry_imports ENABLE ROW LEVEL SECURITY;
ALTER TABLE geonaf.territory_versions ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
  api_role text;
  geonaf_table text;
BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      EXECUTE 'REVOKE ALL ON SCHEMA geonaf FROM ' || quote_ident(api_role);
      EXECUTE 'REVOKE ALL ON ALL TABLES IN SCHEMA geonaf FROM ' || quote_ident(api_role);
      EXECUTE 'REVOKE ALL ON ALL SEQUENCES IN SCHEMA geonaf FROM ' || quote_ident(api_role);
      EXECUTE 'REVOKE ALL ON ALL FUNCTIONS IN SCHEMA geonaf FROM ' || quote_ident(api_role);
    END IF;
  END LOOP;
  FOREACH geonaf_table IN ARRAY ARRAY['licences', 'data_sources', 'source_releases', 'geometries',
      'territory_kinds', 'legal_statuses', 'territories', 'registry_imports', 'territory_versions'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'geonaf_reader') THEN
      EXECUTE 'CREATE POLICY geonaf_reader_select ON geonaf.' || quote_ident(geonaf_table)
           || ' FOR SELECT TO geonaf_reader USING (true)';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'geonaf_importer') THEN
      EXECUTE 'CREATE POLICY geonaf_importer_select ON geonaf.' || quote_ident(geonaf_table)
           || ' FOR SELECT TO geonaf_importer USING (true)';
      IF geonaf_table IN ('data_sources', 'source_releases', 'geometries', 'territories', 'registry_imports',
                          'territory_versions') THEN
        EXECUTE 'CREATE POLICY geonaf_importer_insert ON geonaf.' || quote_ident(geonaf_table)
             || ' FOR INSERT TO geonaf_importer WITH CHECK (true)';
      END IF;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'geonaf_importer') THEN
    CREATE POLICY geonaf_importer_close ON geonaf.registry_imports FOR UPDATE TO geonaf_importer
      USING (finished_at IS NULL) WITH CHECK (finished_at IS NOT NULL);
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'geonaf_reader') THEN
    GRANT USAGE ON SCHEMA geonaf TO geonaf_reader;
    GRANT SELECT ON ALL TABLES IN SCHEMA geonaf TO geonaf_reader;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'geonaf_importer') THEN
    GRANT USAGE ON SCHEMA geonaf TO geonaf_importer;
    GRANT SELECT ON ALL TABLES IN SCHEMA geonaf TO geonaf_importer;
    GRANT INSERT ON geonaf.data_sources, geonaf.source_releases, geonaf.geometries, geonaf.territories,
                    geonaf.territory_versions, geonaf.registry_imports TO geonaf_importer;
    GRANT UPDATE (finished_at, records_seen, records_inserted, records_existing, fingerprints_sha256)
      ON geonaf.registry_imports TO geonaf_importer;
    GRANT USAGE ON ALL SEQUENCES IN SCHEMA geonaf TO geonaf_importer;
  END IF;
END $$;
